T["All: Never stand in front of or behind Onyxia (breath/tail).\nPhase 2 from 65%: dodge fireballs, kill whelps at once.\nPhase 3 from 40%: fear - grounding totem and fear ward ready.\nTank: Onyxia with her back to the wall, head away from the raid.\nTank: phase 3 take aggro back at once.\nHealer: tank first, spread out in phase 2.\nDPS: go full only after 3 sunders from the tank.\nDPS: phase 2: whelps before Onyxia."] = "Todos: Nunca fique na frente ou atrás de Onyxia (sopro/cauda).\nFase 2 a partir de 65%: desvie das bolas de fogo, mate os filhotes na hora.\nFase 3 a partir de 40%: medo - Totem do Aterramento e Proteção contra Medo prontos.\nTanque: Onyxia de costas para a parede, cabeça longe da raide.\nTanque: na fase 3 recupere a ameaça na hora.\nCurador: tanque tem prioridade, fiquem espalhados na fase 2.\nDPS: só ataque com tudo após 3 Fender Armadura do tanque.\nDPS: fase 2: filhotes antes de Onyxia."
T["All: swarm target: run out.\nTank: infernal tank off to the side.\nHealer: remove sleep where possible.\nDPS: ignore infernals, everything on the boss."] = "Todos: alvo do enxame: saia.\nTanque: tanque dos infernais afastado.\nCurador: remova o sono onde possível.\nDPS: ignore os infernais, tudo no chefe."
T["All: leave Death and Decay at once.\nTank: hold the middle, don't move during frost nova.\nHealer: heal the ice block target fast.\nDPS: ranged spread wide (icebolt chain)."] = "Todos: saiam de Morte e Decomposição na hora.\nTanque: segure no meio, não se mova durante a Nova Congelante.\nCurador: cure rápido o alvo do bloco de gelo.\nDPS: à distância bem espalhados (corrente de Seta de Gelo)."
