T["Automatic: every 10 minutes and on logout Oasis stores a snapshot in the saved variables (WTF/Account/<account>/SavedVariables/Oasis.lua). The program Tools/oasis_export.py reads the file, turns it into JSON and can send it to your web page. Addons have no internet access - this is the safe way."] = "Automático: a cada 10 minutos e ao sair o Oasis guarda um instantâneo nas variáveis salvas (WTF/Account/<conta>/SavedVariables/Oasis.lua). O programa Tools/oasis_export.py lê o arquivo, gera JSON e pode enviá-lo para sua página web. Addons não têm acesso à internet - este é o caminho seguro."
T["Automatic: dungeons fitting your level, otherwise all open ones."] = "Automático: masmorras adequadas ao seu nível, senão todas as abertas."
