T["View demo"] = "Ver demonstração"
T["Demo data is only available in the developer version."] = "Dados de demonstração só existem na versão de desenvolvedor."
T["Demo: order would be sent."] = "Demo: o pedido seria enviado."
T["Demo: sample prices, only visible to you"] = "Demo: preços de exemplo, visíveis só para você"
T["Demo: quest would be shared."] = "Demo: a missão seria compartilhada."
T["Demo: plays a ready check with the sample group."] = "Demo: executa uma verificação de prontidão com o grupo de exemplo."
T["Demo: would notify %s."] = "Demo: avisaria %s."
T["Demo: would whisper %s."] = "Demo: sussurraria para %s."
T["Demo: would invite %s."] = "Demo: convidaria %s."
T["You'll find the download in our Discord."] = "O download está no nosso Discord."
T["You can also drag the button around the minimap."] = "Você também pode mover o botão direto no minimapa com o mouse."
T["The raid simulator is only available in the developer version."] = "O simulador de raide só existe na versão de desenvolvedor."
T["Only leadership, raid leaders and raid assistants may edit the raid plan."] = "O plano de raide pode ser editado pela liderança da guilda, líderes de raide e assistentes de raide."
T["WoW can't show this class's talent tree here. You can copy the export string below."] = "O WoW não consegue mostrar aqui a árvore de talentos desta classe. O texto de exportação pode ser copiado abaixo."
T["Delete the whole history with %s? Saved messages are deleted too."] = "Apagar todo o histórico com %s? As mensagens salvas também serão apagadas."
T["The order goes to every crafter with this recipe - whoever has time takes it."] = "O pedido vai para todos os artesãos com esta receita - quem tiver tempo aceita."
T["The order is withdrawn for everyone."] = "O pedido será retirado para todos."
T["The customer is told it's ready."] = "O solicitante é avisado de que está pronto."
T["The requester will be notified."] = "O solicitante é avisado."
T["The bazaar is empty"] = "O bazar está vazio"
T["The Barrens chat with its sayings"] = "O chat dos Sertões com suas frases"
T["The client delivers no skills right now - wait a moment after logging in."] = "O cliente não está fornecendo habilidades agora - espere um pouco após entrar."
T["The dungeon compass: which dungeon fits, what drops there for you."] = "A bússola de masmorras: qual masmorra combina, o que cai lá para você."
T["The enemy was not in front of you. It was behind you. The whole time."] = "O inimigo não estava na sua frente. Estava atrás de você. O tempo todo."
T["The group leader can make you an assistant."] = "O líder do grupo pode tornar você assistente."
T["The fight was locked at first and was recorded afterwards."] = "O combate estava bloqueado e foi avaliado depois."
T["The button can no longer be dragged"] = "O botão não pode mais ser movido com o mouse"
T["The link applies to all officers."] = "O link vale para todas as lideranças."
T["The market uses prices from the AH addon Midas. As soon as you or a guild member scans the AH with Midas, this page unlocks."] = "O mercado usa preços do addon de casa de leilões Midas. Assim que você ou alguém da guilda escanear a casa de leilões com o Midas, esta página é liberada."
T["Play-time tracking is off. Turn it on and Oasis learns a little more every evening."] = "O registro dos horários de jogo está desligado. Ligue-o e o Oasis aprende a cada noite."
T["The Oasis rank is Oasis's guild rank - it rises by playing together, helping, crafting, events and badges."] = "O rank Oasis é o rank de guilda do Oasis - ele sobe jogando junto, ajudando, com profissões, eventos e emblemas."
T["This person's online sound is muted for you."] = "O som de online desta pessoa está desligado para você."
T["The Oasis window border glows in your colour"] = "A borda da janela do Oasis brilha na sua cor"
T["The ring shows who has nothing open."] = "O anel mostra quem está sem pendências."
T["The Stone Eater"] = "O Devorador de Pedras"
T["That date is in the past."] = "O evento está no passado."
T["Details"] = "Detalhes"
T["Tue"] = "Ter"
T["Diagnostics and sync"] = "Diagnóstico e sincronização"
T["Diamond"] = "Diamante"
T["Diamond = Banish (Warlock)"] = "Diamante = Banir (Bruxo)"
T["Visited the bank. Just counting real quick."] = "Visitou o banco. Hora de recontar."
T["The ban list is empty."] = "A lista de banidos está vazia."
T["The chat input was touched by Oasis (e.g. 'Whisper' button), then /target was typed."] = "A entrada do chat foi tocada pelo Oasis (ex.: botão 'Sussurrar'), depois foi digitado /target."
T["The chat input was touched by Oasis (e.g. 'Whisper' button), then a /cast command was typed there."] = "A entrada do chat foi tocada pelo Oasis (ex.: botão 'Sussurrar'), depois foi digitado ali um comando /cast."
T["The chat input was touched by Oasis, then /focus was typed."] = "A entrada do chat foi tocada pelo Oasis, depois foi digitado /focus."
T["The chat input was touched by Oasis, then a spell command was typed."] = "A entrada do chat foi tocada pelo Oasis, depois foi digitado um comando de feitiço."
T["Dungeon maps have no coordinates. Click here, then on the spot where you stand. Done at two distant spots, Oasis shows you and your group on the map - for the whole guild."] = "Os mapas de masmorra não têm coordenadas. Clique aqui e depois no ponto do mapa onde você está agora. Feito em dois pontos bem distantes, o Oasis mostra você e seu grupo no mapa - para a guilda toda."
T["The guild will be notified"] = "A guilda é avisada"
T["The guild can see whom you react to. Default: off"] = "A guilda vê a quem você responde. Padrão: desligado"
T["The guild sees your fire on the map for %d minutes."] = "A guilda vê sua fogueira no mapa por %d minutos."
T["The guild sees your achievements in the chronicle"] = "A guilda vê na crônica o que você alcançou"
T["The guild isn't looking for anything from this dungeon."] = "A guilda não procura nada desta masmorra no momento."
T["Your guild doesn't award loot points yet - your values appear once the raid leaders start a raid."] = "A guilda ainda não distribui pontos de saque - seus valores aparecem assim que a liderança de raide iniciar uma raide."
T["The guild bank hasn't been read yet"] = "O banco da guilda ainda não foi lido"
T["The guild leadership names raid leaders and assistants under Crown > Modules > Raids & Loot (by name or from a guild rank). In a running raid, the raid leader and assistants count too."] = "A liderança da guilda nomeia líderes e assistentes de raide em Coroa > Módulos > Raides e saque (nomes ou a partir do cargo). Em uma raide em andamento também contam o líder e os assistentes da raide."
T["The guild leadership names raid leaders under Crown > Modules > Raids & Loot. In a running raid, the raid leader and assistants count too."] = "A liderança da guilda nomeia líderes de raide em Coroa > Módulos > Raides e saque. Em uma raide em andamento também contam o líder e os assistentes da raide."
T["The guild leadership names raid leaders under Crown > Modules > Raids & Loot. In a running raid, the raid leader counts too."] = "A liderança da guilda nomeia líderes de raide em Coroa > Módulos > Raides e saque. Em uma raide em andamento também conta o líder da raide."
T["The guild leadership only allows group searches from a higher rank."] = "A liderança da guilda só permite buscas de grupo a partir de um cargo mais alto."
T["The guild leadership only allows polls from a higher rank."] = "A liderança da guilda só permite enquetes a partir de um cargo mais alto."
T["The guild leadership has disabled the partner search."] = "A liderança da guilda desativou a busca por companheiros."
T["The guild leadership has disabled open invites - challenge someone directly."] = "A liderança da guilda desativou convites abertos - desafie alguém diretamente."
T["The guild leadership sets which ranks may do this under Crown > Modules."] = "A liderança da guilda define em Coroa > Módulos quais cargos podem fazer isso."
T["WoW's guild finder helps - neutral, no ads."] = "A busca de guildas do WoW ajuda a encontrar - neutra, sem propaganda."
T["Only the guild master sets the limit. Rank 1 = guild master."] = "O limite só é definido pelo Mestre da Guilda. Cargo 1 = Mestre da Guilda."
T["The buttons put the command into the chat line - it only runs when you press Enter."] = "Os botões escrevem o comando na linha de chat - ele só é executado com Enter."
T["The shortcuts are also in WoW's key bindings under AddOns > Oasis. Esc closes the Oasis window (not in combat - there Esc belongs to the game)."] = "Os atalhos também estão nas Teclas de Atalho do WoW em AddOns > Oasis. Esc fecha a janela do Oasis (não em combate - lá o Esc pertence ao jogo)."
T["The shortcuts are also in WoW's key bindings under AddOns > Oasis. Esc closes the Oasis window as long as you last clicked into it."] = "Os atalhos também estão nas Teclas de Atalho do WoW em AddOns > Oasis. Esc fecha a janela do Oasis enquanto você clicou nela por último."
T["The bar rolls up out of view; move the mouse to the top edge and it comes down (only when docked at the top)"] = "A barra se recolhe para cima; leve o mouse à borda superior e ela desce (só quando ancorada no topo)"
T["The reservation line only appears while you are in a group or raid"] = "A linha de reserva só aparece quando você está em um grupo ou raide"
T["The Scale of the Sands"] = "Os Guardiões das Areias"
T["Opened the world map. Where was north again?"] = "Abriu o mapa-múndi. Onde era o norte mesmo?"
T["The real bar above shows every change instantly"] = "A barra real no topo mostra cada mudança na hora"
T["The first 20 stamina give 1 health each, every further point 10."] = "Os primeiros 20 de Vigor dão 1 cada, cada ponto extra dá 10 de vida."
T["Most ghost runs in the guild. The graveyard has a bench with your name on it."] = "Mais corridas de espírito da guilda. O cemitério tem um banco com seu nome."
