T["Who sends data that others reject (no permission, forged author, made-up entries). An unmodified Oasis practically never does this - a hint, not proof."] = "Quem envia dados rejeitados pelos outros (sem permissão, autor falso, entradas inventadas). Um Oasis inalterado quase nunca faz isso - um indício, não prova."
T["Anyone who registers interest appears in a matching slot. Once there is an event, sign up directly on its card."] = "Quem demonstra interesse aparece aqui num horário adequado. Com evento marcado, você se inscreve direto no cartão."
T["Who in the guild has the item on their wishlist"] = "Quem da guilda tem o item na lista de desejos"
T["Who sees this section in the navigation (leadership always sees everything)"] = "Quem vê a área na navegação (a liderança sempre vê tudo)"
T["Who left the guild or was removed. If someone returns, Oasis notifies guild management."] = "Quem saiu ou foi removido da guilda. Se alguém voltar, o Oasis avisa a liderança."
T["Who sees the crown at the top. Without rights it is grey and only opens a preview."] = "Quem vê a coroa no topo. Sem permissão ela fica cinza e só abre uma prévia."
