T["Who could join?"] = "Quem poderia ir?"
T["Whoever shows up often and has received little gets first pick on 'Need'. Part of the points decays every week."] = "Quem participa muito e recebeu pouco vem primeiro em 'Necessidade'. Toda semana parte dos pontos expira."
T["Anyone who signs up with a fitting role is invited to your group right away."] = "Quem se inscrever com função adequada é convidado na hora ao seu grupo."
T["Who stands where with which faction? Close to the goal, farm together, progress this week"] = "Quem está onde em cada facção? Quase no objetivo, farmar juntos, progresso da semana"
T["Who deals, heals and takes the most?"] = "Quem causa mais dano, cura mais, aguenta mais?"
