T["Stats"] = "Atributos"
T["stats do nothing for your role"] = "Atributos não ajudam sua função"
T["stats for info only"] = "Atributos só informativos"
T["Stats, yearbook, daily goal, records and adventures of your character."] = "Atributos, anuário, meta diária, recordes e aventuras do seu personagem."
T["Stats: +healing, intellect, spirit, mp5;Weapon: staff or one-hander + off-hand with healing;Healing: Rejuvenation and Regrowth ahead, Healing Touch for big hits;Tip: Innervate for mana, Rebirth for fallen healers"] = "Atributos: +Cura, Intelecto, Espírito, reg. de mana;Arma: cajado ou uma mão + mão secundária com cura;Curar: Rejuvenescer e Recrescimento antes, Toque de Cura para dano grande;Dica: Inervar para mana, Renascimento para curadores caídos"
T["Stats: +healing, intellect, spell crit (Illumination refunds mana), mp5;Weapon: one-hander + off-hand/shield with healing;Healing: Flash of Light for small damage, Holy Light (low rank) for big hits;Tip: hand out blessings, Divine Protection when you pull aggro"] = "Atributos: +Cura, Intelecto, crítico mágico (Iluminação devolve mana), reg. de mana;Arma: uma mão + secundária/escudo com cura;Curar: Clarão de Luz para dano pequeno, Luz Sagrada (patente baixa) para dano grande;Dica: distribuir Bênçãos, Proteção Divina se puxar aggro"
T["Stats: +healing, mp5, intellect - spirit does little;Weapon: one-hander + shield with healing;Healing: Chain Heal for groups, Healing Wave (low rank) for the tank;Tip: drop Mana Spring Totem, Earth Shield on the tank"] = "Atributos: +Cura, reg. de mana (MP5), Intelecto - Espírito ajuda pouco;Arma: uma mão + escudo com cura;Curar: Cura em Cadeia para grupos, Onda Curativa (patente baixa) para o tanque;Dica: Totem de Fonte de Mana, Escudo Terrestre no tanque"
T["Stats: +healing, spirit (Meditation: regen while casting), intellect, mp5;Weapon: staff or one-hander + off-hand with healing, wand;Healing: Renew and Power Word: Shield ahead, Greater Heal (low rank) for the tank;Tip: Prayer of Healing for the group, Fade on aggro"] = "Atributos: +Cura, Espírito (Meditação: regenera ao conjurar), Intelecto, reg. de mana;Arma: cajado ou uma mão + secundária com cura, varinha;Curar: Renovar e Palavra de Poder: Escudo antes, Cura Maior (patente baixa) para o tanque;Dica: Prece de Cura para o grupo, Desvanecer com aggro"
T["Stats: armor (bear form multiplies it), stamina, agility (dodge + armor);Weapon: damage doesn't matter - only the stats (staff/polearm with stamina);Rotation: Maul, Swipe for packs, Demoralizing Roar;Tip: strength for more threat, Enrage to start"] = "Atributos: Armadura (Forma de Urso multiplica), Vigor, Agilidade (esquiva + armadura);Arma: irrelevante para dano - só atributos contam (cajado/haste com Vigor);Rotação: Espancar, Golpe Giratório para grupos, Rugido Desmoralizante;Dica: Força para mais ameaça, Enfurecer no início"
T["Stats: strength (1 point = 2 AP), agility (AP + crit), crit, hit up to +9 %;Weapon: damage doesn't matter - only the stats;Rotation: Claw/Shred for combo points, then Ferocious Bite;Tip: powershift (recast form) for energy, open from stealth"] = "Atributos: Força (1 ponto = 2 PA), Agilidade (PA + crítico), crítico, acerto até +9 %;Arma: irrelevante para dano - só atributos contam;Rotação: Garra/Retalhar para pontos de combo, depois Mordida Feroz;Dica: trocar de forma para energia, saltar da Espreita"
T["Stats: strength (1 point = 2 AP), crit (procs Flurry = faster swings), hit up to +9 %;Weapon: slow two-hander - Windfury procs per swing, so slower = more damage;Rotation: Windfury Weapon, Stormstrike, Earth Shock;Tip: Strength of Earth and Windfury Totem for the group"] = "Atributos: Força (1 ponto = 2 PA), crítico (ativa Rajada = golpes mais rápidos), acerto até +9 %;Arma: duas mãos lenta - Fúria dos Ventos acerta por golpe, quanto mais lenta mais dano;Rotação: Arma Fúria dos Ventos, Ataque Tempestuoso, Choque Terrestre;Dica: Totem de Força da Terra e Totem de Fúria dos Ventos para o grupo"
T["Stats: strength (1 point = 2 AP), crit, hit up to +9 %;Weapon: slow two-hander - seals and Judgement scale per swing;Rotation: Seal of Righteousness/Command, Judgement, reapply seal;Tip: Consecration only with enough mana, Blessing of Might on yourself"] = "Atributos: Força (1 ponto = 2 PA), crítico, acerto até +9 %;Arma: duas mãos lenta - Selo e Julgamento agem por golpe;Rotação: Selo da Retidão/do Comando, Julgamento, renovar selo;Dica: Consagração só com mana sobrando, Bênção do Poderio para você"
T["Stats: hit up to +9 %, agility (1 AP, ~29 = 1 % crit), AP, crit;Weapon: Combat = fast off-hand, slow main hand (Sinister Strike); daggers for Backstab;Rotation: build combo points, keep Slice and Dice up, then Eviscerate;Tip: dual wielding misses white hits more often - hit matters most"] = "Atributos: acerto até +9 %, Agilidade (1 PA, ~29 = 1 % crítico), PA, crítico;Arma: Combate = secundária rápida, principal lenta (Golpe Sinistro); adagas para Apunhalar;Rotação: acumular pontos de combo, manter Picar e Fatiar, depois Eviscerar;Dica: com duas armas golpes normais erram mais - acerto é o mais importante"
T["Stats: hit up to +9 %, agility (2 ranged AP, ~53 = 1 % crit), AP, intellect;Weapon: slow ranged weapon (big damage per shot), melee weapon for stats;Rotation: Hunter's Mark, Auto Shot, Aimed Shot/Multi-Shot in between;Tip: feed your pet and keep it happy, Freezing Trap (square) for control"] = "Atributos: acerto até +9 %, Agilidade (2 PA à distância, ~53 = 1 % crítico), PA, Intelecto;Arma: arma à distância lenta (dano alto por tiro), arma corpo a corpo com atributos;Rotação: Marca do Caçador, Tiro Automático, Tiro Mirado/Tiro Múltiplo entre eles;Dica: alimentar o ajudante e mantê-lo feliz, Armadilha Congelante como controle"
T["Stats: hit up to +9 %, strength (1 point = 2 AP), crit (~20 agility = 1 %);Weapon: slow two-hander (Mortal Strike, Heroic Strike scale per swing);Rotation: build rage, Mortal Strike / Bloodthirst, Whirlwind, spare rage into Heroic Strike;Tip: Battle Shout before the pull, Execute below 20 % health"] = "Atributos: acerto até +9 %, Força (1 ponto = 2 PA), crítico (~20 Agilidade = 1 %);Arma: duas mãos lenta (Golpe Mortal, Golpe Heroico agem por golpe);Rotação: gerar raiva, Golpe Mortal / Sede de Sangue, Redemoinho, raiva extra em Golpe Heroico;Dica: Brado de Batalha antes do combate, Executar abaixo de 20 % de vida"
T["Stats: defense (440 = crit immune vs bosses at 60), stamina, armor, block;Weapon: one-hander + shield, fast weapon = more rage;Rotation: Shield Slam/Revenge, Sunder Armor on the target, Heroic Strike with high rage;Tip: hit helps so Taunt and abilities don't miss"] = "Atributos: Defesa (440 = imune a crítico de chefes no 60), Vigor, Armadura, bloqueio;Arma: uma mão + escudo, arma rápida = mais raiva;Rotação: Escudada/Revanche, Fender Armadura no alvo, Golpe Heroico com muita raiva;Dica: acerto ajuda para Provocar e habilidades não errarem"
T["Stats: defense, stamina, armor, then spell damage for more threat;Weapon: one-hander (ideally spell damage) + shield;Rotation: Righteous Fury on, Consecration for packs, keep Holy Shield up;Tip: mana is tight - use Seal of Wisdom or some intellect"] = "Atributos: Defesa, Vigor, Armadura, depois dano mágico para mais ameaça;Arma: uma mão (de preferência com dano mágico) + escudo;Rotação: ligar Fúria Justa, Consagração para grupos, manter Escudo Sagrado;Dica: mana é pouca - leve Selo da Sabedoria ou Intelecto"
T["Stats: spell damage, spell crit (Elemental Focus saves mana), intellect, mp5;Weapon: one-hander + shield/off-hand with spell damage;Rotation: spam Lightning Bolt, Chain Lightning on packs, Flame Shock;Tip: spell hit up to +16 % in raids, Mana Spring Totem against oom"] = "Atributos: dano mágico, crítico mágico (Foco Elemental poupa mana), Intelecto, reg. de mana;Arma: uma mão + escudo/secundária com dano mágico;Rotação: spam de Raio, Cadeia de Raios em grupos, Choque Flamejante;Dica: acerto mágico até +16 % na raide, Totem de Fonte de Mana contra mana vazia"
T["Stats: spell damage, spell crit, intellect, spell hit up to +16 % in raids;Weapon: staff or one-hander + off-hand with spell damage;Rotation: Moonfire + Insect Swarm, then Wrath or Starfire;Tip: Innervate yourself when mana runs low"] = "Atributos: dano mágico, crítico mágico, Intelecto, acerto mágico até +16 % na raide;Arma: cajado ou uma mão + secundária com dano mágico;Rotação: Fogo Lunar + Enxame de Insetos, depois Ira ou Fogo Estelar;Dica: Inervar em si mesmo quando a mana acabar"
T["Stats: spell damage, spell hit up to +16 % (raid), stamina, intellect;Weapon: staff or dagger + off-hand with spell damage, wand for leftover mana;Rotation: Corruption + curse, then Shadow Bolt; Life Tap instead of drinking;Tip: stamina pays off twice (Life Tap, Voidwalker/Soul Link)"] = "Atributos: dano mágico, acerto mágico até +16 % (raide), Vigor, Intelecto;Arma: cajado ou adaga + secundária com dano mágico, varinha para mana restante;Rotação: Corrupção + maldição, depois Seta Sombria; Drenar Vida em vez de beber;Dica: Vigor vale em dobro (Drenar Vida, Emissário do Caos/Elo Anímico)"
T["Stats: spell damage, spell hit up to +16 % (raid), spirit for mana;Weapon: staff or one-hander + off-hand with spell damage;Rotation: Shadow Word: Pain, Mind Blast, Mind Flay;Tip: stay in Shadowform, Vampiric Embrace heals the group"] = "Atributos: dano mágico, acerto mágico até +16 % (raide), Espírito para mana;Arma: cajado ou uma mão + secundária com dano mágico;Rotação: Palavra Sombria: Dor, Explosão Mental, Tortura Mental;Dica: Forma de Sombra sempre ligada, Abraço Vampírico cura o grupo"
T["Stats: spell damage, then spell hit up to +16 % (raid bosses), intellect, spell crit;Weapon: staff with spell damage, plus a wand for leftover mana;Rotation: spam Frostbolt or Fireball, Evocation when out of mana;Leveling: intellect and spirit = less downtime, sheep (moon) in groups"] = "Atributos: dano mágico, depois acerto mágico até +16 % (chefes de raide), Intelecto, crítico mágico;Arma: cajado com dano mágico, mais uma varinha para mana restante;Rotação: spam de Seta de Gelo ou Bola de Fogo, Evocação com mana vazia;Upar: Intelecto e Espírito = menos pausas, em grupo use Metamorfose (Lua)"
