T["Shows BETTER / WORSE / CAN'T EQUIP with effect (DPS, health, armor) and a stats table. Blizzard's comparison then only appears with Shift. If nesUI is loaded with its own comparison, Oasis shows nothing (avoids doubles) - turn it off there with /nes vergleich."] = "Mostra MELHOR / PIOR / NÃO EQUIPÁVEL com impacto (DPS, vida, armadura) e tabela de atributos. A comparação da Blizzard só aparece com Shift. Se o nesUI estiver carregado com comparação própria, o Oasis não mostra nada (senão duplica) - desative lá com /nes vergleich."
