T["1.  Keep the combat log on (Settings > Areas > Combat board, on by default).\n2.  After playing, double-click ImportCrits.bat in the Oasis folder.\n3.  /reload in game - your highest crit shows here and is shared with the guild."] = "1.  Deixe o registro de combate ligado (Configurações > Áreas > Classificação de combate, ligado por padrão).\n2.  Depois de jogar, dê dois cliques em ImportCrits.bat na pasta do Oasis.\n3.  /reload no jogo - seu maior crítico aparece aqui e é compartilhado com a guilda."
