T["All fonts under the SIL Open Font License 1.1"] = "Todas as fontes sob a SIL Open Font License 1.1"
T["All: Burning Adrenaline: run out of the raid AT ONCE (you are about to die).\nAll: Full resources at the start - use everything.\nTank: Set a tank order (Adrenaline on the tank).\nDD: Not in front of or behind the dragon."] = "All: Adrenalina Ardente: corra para fora da raide NA HORA (você vai morrer).\nAll: Recursos cheios no início - use tudo.\nTank: Definir ordem dos tanks (Adrenalina no tank).\nDD: Não fique na frente nem atrás do dragão."
T["All: Do not let the 8 Firesworn die near the raid (explosion).\nTank: Each add tank pulls their Firesworn away, warlocks banish.\nHealer: Dispel, keep an eye on the add tanks.\nDD: Garr first, adds only when called."] = "All: Não deixem os 8 Firesworn morrerem perto da raide (explosão).\nTank: Cada tank de add puxa seu Firesworn para longe, bruxos banem.\nHealer: Dissipar, de olho nos tanks de add.\nDD: Garr primeiro, adds só quando chamado."
T["All: Tank the two Core Ragers away from the boss, do not kill them.\nTank: Swap the Golemagg tank when Magma Splash stacks too high.\nDD: Only on Golemagg."] = "All: Tankar os dois Core Ragers longe do chefe, não matar.\nTank: Trocar o tank do Golemagg quando Magma Splash acumular demais.\nDD: Só no Golemagg."
T["All: The 4 priests first, they heal each other.\nTank: Keep Sulfuron and the priests apart.\nDD: Interrupt! Stop the priests' Dark Mending."] = "All: Primeiro os 4 sacerdotes, eles se curam entre si.\nTank: Manter Sulfuron e os sacerdotes separados.\nDD: Interromper! Parar o Dark Mending dos sacerdotes."
T["All: Fire protection! Wrath of Ragnaros knocks melee back - then get back in.\nAll: Sons phase (after 3 min or when he submerges): kill all Sons of Flame.\nTank: Second tank ready when the first is knocked away.\nHealer: Spread out, ranged not too close (Lava Burst).\nDD: Melee: keep mana under control, ranged keep your distance."] = "All: Proteção contra fogo! Ira de Ragnaros arremessa o corpo a corpo - depois voltem.\nAll: Fase dos Filhos (após 3 min ou quando ele submerge): matar todos os Filhos da Chama.\nTank: Segundo tank pronto quando o primeiro for arremessado.\nHealer: Espalhados, distância não muito perto (Estouro de Lava).\nDD: Corpo a corpo: mana sob controle, distância mantém afastado."
T["All: Flame Buffet stacks - ranged behind pillars to let it drop.\nTank: Two tanks behind pillars, Wing Buffet knocks back.\nDD: Onyxia Scale Cloak required."] = "All: Flame Buffet acumula - distância atrás dos pilares para deixar cair.\nTank: Dois tanks atrás dos pilares, Wing Buffet empurra.\nDD: Manto de Escamas de Onyxia obrigatório."
T["All: Remove Gehennas' Curse (reduced healing) at once.\nAll: Get out of the Rain of Fire.\nTank: Tank the two Flamewakers apart.\nDD: Flamewakers first, then Gehennas."] = "All: Remover a Maldição de Gehennas (menos cura) na hora.\nAll: Sair da Chuva de Fogo.\nTank: Tankar os dois Flamewakers separados.\nDD: Flamewakers primeiro, depois Gehennas."
T["All: Remove Lucifron's Curse and Impending Doom at once (mages/druids, priests/paladins).\nTank: Tank the two guards apart - mind control!\nHealer: Spread out, dispel mind-controlled players.\nDD: Guards first, then Lucifron."] = "All: Remover Maldição de Lucifron e Impending Doom na hora (magos/druidas, sacerdotes/paladinos).\nTank: Tankar os dois guardas separados - controle mental!\nHealer: Fiquem espalhados, dissipar jogadores controlados.\nDD: Primeiro os guardas, depois Lucifron."
T["All: Living Bomb: run out of the raid AT ONCE!\nAll: Inferno - away from the boss, dispel Ignite Mana.\nTank: Hold the middle, step out briefly on Inferno.\nDD: Melee back off on Inferno."] = "All: Bomba Viva: corra para fora da raide NA HORA!\nAll: Inferno - longe do chefe, dissipar Ignite Mana.\nTank: Segurar o meio, sair um pouco no Inferno.\nDD: Corpo a corpo recua no Inferno."
T["All: Watch the guards' magic reflection/damage shield - stop damage then.\nTank: One guard per tank, mages sheep the elite guards.\nDD: Healer guards (Flamewaker Healer) first."] = "All: Atenção ao reflexo de magia/escudo de dano dos guardas - aí parem o dano.\nTank: Um guarda por tank, magos transformam os guardas de elite.\nDD: Guardas curandeiros (Flamewaker Healer) primeiro."
T["All: Never stand in front of or behind Onyxia (breath and tail sweep).\nAll: Phase 2 (65%): dodge fireballs, stay out of the cave entrances.\nAll: Phase 3 (40%): fear - Fear Ward/Tremor Totem ready, avoid the lava cracks.\nTank: Onyxia sideways at the wall, head away from the raid.\nTank: Phase 2: pick up the whelps. Phase 3: get aggro back at once.\nHealer: Tank has priority, spread out in phase 2.\nDD: Wait for 3 attacks of the tank. Phase 2: whelps first."] = "All: Nunca fique na frente nem atrás da Onyxia (sopro e rabada).\nAll: Fase 2 (65%): desviar das bolas de fogo, fora das entradas das cavernas.\nAll: Fase 3 (40%): medo - Proteção contra Medo/Totem Sísmico prontos, evitar as fendas de lava.\nTank: Onyxia de lado na parede, cabeça longe da raide.\nTank: Fase 2: pegar os filhotes. Fase 3: recuperar a aggro na hora.\nHealer: Tank tem prioridade, espalhados na fase 2.\nDD: Esperar 3 ataques do tank. Fase 2: filhotes primeiro."
T["All: Panic - Fear Ward/Tremor Totem, hunters: Tranquilizing Shot on Frenzy.\nAll: Get out of the lava fire on the ground.\nTank: Magmadar with his back to the raid.\nDD: Ranged spread out at the back."] = "All: Pânico - Proteção contra Medo/Totem Sísmico, caçadores: Tiro Tranquilizante no Frenesi.\nAll: Sair do fogo de lava no chão.\nTank: Magmadar de costas para a raide.\nDD: Distância espalhada atrás."
T["All: Phase 1: dragonkin from both sides, watch the class calls.\nAll: Phase 3 (20%): the skeletons rise again - kill them again.\nTank: Nefarian at the wall, fear - Fear Ward.\nHealer: Class call for priests: healing hurts - be careful.\nDD: Hunters/warriors: watch the class calls (weapons gone, stance)."] = "All: Fase 1: dracônicos dos dois lados, atenção aos chamados de classe.\nAll: Fase 3 (20%): os esqueletos se levantam - matar de novo.\nTank: Nefarian na parede, medo - Proteção contra Medo.\nHealer: Chamado de classe dos sacerdotes: cura causa dano - cuidado.\nDD: Caçadores/guerreiros: atenção aos chamados de classe (sem armas, postura)."
T["All: Phase 1: destroy the eggs (mind control via the orb), pick up the adds.\nAll: After all eggs: boss in the room - Fire Nova.\nTank: Gather the adds at the stairs.\nDD: Mages and dragonkin first."] = "All: Fase 1: destruir os ovos (controle mental pelo orbe), pegar os adds.\nAll: Depois de todos os ovos: chefe na sala - Nova de Fogo.\nTank: Juntar os adds nas escadas.\nDD: Magos e dracônicos primeiro."
T["All: Frenzy - hunters: Tranquilizing Shot.\nTank: Two tanks, watch Wing Buffet.\nDD: Onyxia Scale Cloak required."] = "All: Frenesi - caçadores: Tiro Tranquilizante.\nTank: Dois tanks, atenção ao Wing Buffet.\nDD: Manto de Escamas de Onyxia obrigatório."
T["All: Shadow of Ebonroc heals the boss - the tank with the debuff swaps.\nTank: Two tanks swap on Shadow.\nDD: Onyxia Scale Cloak required."] = "All: Shadow of Ebonroc cura o chefe - o tank com o debuff troca.\nTank: Dois tanks trocam na Sombra.\nDD: Manto de Escamas de Onyxia obrigatório."
T["All: Knockback - stand against the wall.\nTank: Two tanks, aggro is split by Knock Away.\nDD: Mortal Strike on the tank: healers be prepared."] = "All: Empurrão - fiquem contra a parede.\nTank: Dois tanks, a aggro é dividida pelo Knock Away.\nDD: Golpe Mortal no tank: curandeiros preparados."
T["All: He teleports - whoever has aggro, do not run away.\nAll: Remove Shazzrah's Curse, Arcane Explosion: melee keep your distance.\nTank: Get back on him right after every blink.\nHealer: Dispel (Deaden Magic)."] = "All: Ele se teleporta - quem tiver aggro, não corra.\nAll: Remover a Maldição de Shazzrah, Explosão Arcana: corpo a corpo mantém distância.\nTank: Voltar nele logo após cada lampejo.\nHealer: Dissipar (Deaden Magic)."
T["All: Two of the five breath types per week - avoid the breath behind the corner.\nAll: Hourglass Sand for the Bronze affliction.\nTank: Tank at the gate, raid behind the corner.\nDD: Tranquilizing Shot on Frenzy."] = "All: Dois dos cinco tipos de sopro por semana - evite o sopro atrás da quina.\nAll: Areia da Ampulheta para a aflição Bronze.\nTank: Tankar no portão, raide atrás da quina.\nDD: Tiro Tranquilizante no Frenesi."
T["Hold Alt: all stats and scoring details. Shift: Blizzard comparison."] = "Segure Alt: todos os atributos e detalhes da nota. Shift: comparação da Blizzard."
T["Release Alt: compact view. Shift: Blizzard comparison."] = "Solte Alt: visão compacta. Shift: comparação da Blizzard."
